import os
from typing import Any, Dict, List, Optional

from google.cloud import documentai


def extract_receipt_fields(
    file_path: str,
    project_id: Optional[str] = None,
    location: Optional[str] = None,
    processor_id: Optional[str] = None,
    mime_type: Optional[str] = None,
) -> Dict[str, Any]:
    project_id = project_id or os.environ["GOOGLE_CLOUD_PROJECT"]
    location = location or os.environ.get("DOCUMENTAI_LOCATION", "us")
    processor_id = processor_id or os.environ["DOCUMENTAI_PROCESSOR_ID"]

    if mime_type is None:
        ext = os.path.splitext(file_path)[1].lower()
        mime_type = {
            ".pdf": "application/pdf",
            ".png": "image/png",
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".tif": "image/tiff",
            ".tiff": "image/tiff",
            ".gif": "image/gif",
            ".bmp": "image/bmp",
            ".webp": "image/webp",
        }.get(ext, "application/octet-stream")

    endpoint = f"{location}-documentai.googleapis.com"
    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": endpoint}
    )

    name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as f:
        content = f.read()

    raw_document = documentai.RawDocument(content=content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    entities = list(getattr(document, "entities", []))

    def entity_text(entity: Any) -> str:
        if getattr(entity, "mention_text", None):
            return entity.mention_text.strip()
        text_anchor = getattr(entity, "text_anchor", None)
        if not text_anchor or not getattr(text_anchor, "text_segments", None):
            return ""
        parts = []
        for seg in text_anchor.text_segments:
            start = int(seg.start_index) if getattr(seg, "start_index", None) else 0
            end = int(seg.end_index)
            parts.append(document.text[start:end])
        return "".join(parts).strip()

    def first_value(type_candidates: List[str]) -> Optional[str]:
        candidates = set(type_candidates)
        for e in entities:
            if getattr(e, "type_", "") in candidates:
                value = entity_text(e)
                if value:
                    return value
        return None

    merchant = first_value(
        [
            "supplier_name",
            "merchant_name",
            "receiver_name",
            "vendor_name",
        ]
    )

    tax = first_value(
        [
            "total_tax_amount",
            "tax_amount",
            "tax",
        ]
    )

    total = first_value(
        [
            "total_amount",
            "net_amount",
            "amount_due",
        ]
    )

    items: List[Dict[str, Any]] = []
    item_types = {"line_item", "item"}
    for e in entities:
        if getattr(e, "type_", "") not in item_types:
            continue

        item_data: Dict[str, Any] = {
            "description": None,
            "quantity": None,
            "unit_price": None,
            "total_price": None,
        }

        for prop in getattr(e, "properties", []):
            prop_type = getattr(prop, "type_", "")
            value = entity_text(prop) or None

            if prop_type in {"line_item/description", "item/description", "description"}:
                item_data["description"] = value
            elif prop_type in {"line_item/quantity", "item/quantity", "quantity"}:
                item_data["quantity"] = value
            elif prop_type in {
                "line_item/unit_price",
                "item/unit_price",
                "unit_price",
            }:
                item_data["unit_price"] = value
            elif prop_type in {
                "line_item/amount",
                "item/amount",
                "amount",
                "line_item/total_amount",
                "item/total_amount",
                "total_amount",
            }:
                item_data["total_price"] = value

        if not any(item_data.values()):
            fallback = entity_text(e)
            if fallback:
                item_data["description"] = fallback

        if any(item_data.values()):
            items.append(item_data)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
